export default async ({ text, selection }, context) => {
  const key = "telegram-photo:" + selection.chatId + ":" + selection.updateId;
  return {
    text,
    chatId: selection.chatId,
    key,
    send: await context.state.insert(key, { status: "pending" }),
  };
};

